<script setup lang="ts">
import { computed } from 'vue';
import DOMPurify from 'dompurify';
import { marked } from 'marked';

defineOptions({ name: 'AgentPreviewMarkdown' });

const props = defineProps<{
  content: string;
}>();

const html = computed(() => {
  const rendered = marked.parse(props.content, {
    async: false,
    breaks: true,
    gfm: true
  }) as string;

  return DOMPurify.sanitize(rendered, {
    FORBID_TAGS: ['form', 'iframe', 'img', 'style'],
    FORBID_ATTR: ['style']
  });
});
</script>

<template>
  <!-- HTML is generated by marked and sanitized with DOMPurify above. -->
  <!-- eslint-disable-next-line vue/no-v-html -->
  <div class="preview-markdown break-words" v-html="html" />
</template>

<style scoped>
.preview-markdown :deep(> :first-child) {
  margin-top: 0;
}

.preview-markdown :deep(> :last-child) {
  margin-bottom: 0;
}

.preview-markdown :deep(p),
.preview-markdown :deep(ul),
.preview-markdown :deep(ol),
.preview-markdown :deep(blockquote),
.preview-markdown :deep(pre),
.preview-markdown :deep(table) {
  margin: 0.5em 0;
}

.preview-markdown :deep(ul),
.preview-markdown :deep(ol) {
  padding-left: 1.5em;
}

.preview-markdown :deep(blockquote) {
  border-left: 3px solid rgba(var(--primary-color), 0.35);
  padding-left: 0.75em;
  opacity: 0.78;
}

.preview-markdown :deep(code) {
  border-radius: 4px;
  background: rgba(127, 127, 127, 0.12);
  padding: 0.1em 0.35em;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

.preview-markdown :deep(pre) {
  overflow-x: auto;
  border-radius: 6px;
  background: rgba(127, 127, 127, 0.12);
  padding: 0.75em;
}

.preview-markdown :deep(pre code) {
  background: transparent;
  padding: 0;
}

.preview-markdown :deep(table) {
  width: 100%;
  border-collapse: collapse;
}

.preview-markdown :deep(th),
.preview-markdown :deep(td) {
  border: 1px solid rgba(127, 127, 127, 0.28);
  padding: 0.35em 0.5em;
}

.preview-markdown :deep(a) {
  color: rgb(var(--primary-color));
  text-decoration: underline;
}
</style>
